// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testFuzz_property(bytes32 assertionId, address caller) public {
        vm.assume(caller != address(this));
        vm.prank(address(this));
        c.assertionDisputedCallback(assertionId);
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSignature("requestPrice(bytes32,uint256,bytes)", bytes32(0), uint256(0), hex""));
        assertTrue(!ok);
    }
}
